#include "../../include/config.h"
#include <Arduino.h>
#include <HardwareSerial.h>

RS485Protocol::RS485Protocol(uint8_t nodeId)
    : _nodeId(nodeId), _baudRate(115200), _parity(0), _stopBits(1) {}

bool RS485Protocol::init() {
    pinMode(PIN_RS485_DE_RE, OUTPUT);
    digitalWrite(PIN_RS485_DE_RE, LOW); // Receive mode

    Serial1.begin(_baudRate, SERIAL_8N1, PIN_RS485_RX, PIN_RS485_TX);
    return true;
}

void RS485Protocol::deinit() {
    Serial1.end();
    digitalWrite(PIN_RS485_DE_RE, LOW);
}

bool RS485Protocol::send(const Frame& frame) {
    digitalWrite(PIN_RS485_DE_RE, HIGH); // Transmit mode

    for (int i = 0; i < sizeof(Frame); i++) {
        Serial1.write(((const uint8_t*)&frame)[i]);
    }

    delayMicroseconds(100);
    digitalWrite(PIN_RS485_DE_RE, LOW); // Receive mode

    return true;
}

bool RS485Protocol::receive(Frame& frame, uint32_t timeout_ms) {
    uint32_t startMillis = millis();

    while (millis() - startMillis < timeout_ms) {
        if (Serial1.available() >= sizeof(Frame)) {
            for (int i = 0; i < sizeof(Frame); i++) {
                ((uint8_t*)&frame)[i] = Serial1.read();
            }
            return true;
        }
        yield();
    }

    return false;
}

void RS485Protocol::setBaudRate(uint32_t baud) {
    _baudRate = baud;
}

void RS485Protocol::setParity(uint8_t parity) {
    _parity = parity;
}

void RS485Protocol::setStopBits(uint8_t stopBits) {
    _stopBits = stopBits;
}
