{"path":"/home/roko/Documents/Projects/myactuator/firmware/esp32/src/utils/pid.cpp","content":"#include "pid.h"

PIDController::PIDController()
    : _kp(1.0f), _ki(0.1f), _kd(0.01f),
      _outputMin(-100.0f), _outputMax(100.0f),
      _integral(0.0f), _prevError(0.0f), _initialized(false) {}

void PIDController::setGains(float kp, float ki, float kd) {
    _kp = kp;
    _ki = ki;
    _kd = kd;
}

void PIDController::setLimits(float outputMin, float outputMax) {
    _outputMin = outputMin;
    _outputMax = outputMax;
}

float PIDController::compute(float setpoint, float measurement, float dt) {
    if (dt <= 0.0f) return 0.0f;

    float error = setpoint - measurement;

    // Proportional
    float proportional = _kp * error;

    // Integral
    _integral += error * dt;
    // Anti-windup
    if (_integral > _outputMax / _ki) _integral = _outputMax / _ki;
    if (_integral < _outputMin / _ki) _integral = _outputMin / _ki;
    float integral = _ki * _integral;

    // Derivative
    float derivative = 0.0f;
    if (_initialized) {
        derivative = _kd * (error - _prevError) / dt;
    }
    _prevError = error;
    _initialized = true;

    // Sum and limit
    float output = proportional + integral + derivative;
    if (output > _outputMax) output = _outputMax;
    if (output < _outputMin) output = _outputMin;

    return output;
}

void PIDController::reset() {
    _integral = 0.0f;
    _prevError = 0.0f;
    _initialized = false;
}
"}

